#!/usr/bin/env bash
# Grok desk self-extracting installer. Code only — secrets are generated on the server.
set -euo pipefail
T=$(mktemp -d); trap "rm -rf $T" EXIT
sed '1,/^__PAYLOAD__$/d' "$0" | base64 -d > $T/code.tgz
echo "3f2b021074bd435a29d1fc626657ee0ca196d65bd05c9b04f254636fd9a95a11  $T/code.tgz" | sha256sum -c --quiet
mkdir -p $T/src && tar -xzf $T/code.tgz -C $T/src
GROK_DESK_SRC=$T/src bash $T/src/deploy/install.sh
exit 0
